  ('f6574aaf-0048-525e-9662-9afecf694743', 'AU-PDGRA', '00000000-0000-0000-0000-000000000001', 'r-a-torrey', 'R. A. Torrey', null, 'R. A. Torrey (1856 to 1928). Real author. The original text is in the public domain; the workbook around it is new Akana material.', 'US', null, null, 'en-GB', false, true, 'active'),
  ('78eda82a-682e-5628-bec0-64ff7957d88b', 'AU-VE8V6', '00000000-0000-0000-0000-000000000001', 'evelyn-underhill', 'Evelyn Underhill', null, 'Evelyn Underhill (1875 to 1941). Real author. The original text is in the public domain; the workbook around it is new Akana material.', 'GB', null, null, 'en-GB', false, true, 'active'),
  ('d89f3271-6676-5020-9c18-6d3190af3bf7', 'AU-MEBAQ', '00000000-0000-0000-0000-000000000001', 'george-macdonald', 'George MacDonald', null, 'George MacDonald (1824 to 1905). Real author. The original text is in the public domain; the workbook around it is new Akana material.', 'GB', null, null, 'en-GB', false, true, 'active'),
  ('4a7514bb-e9a1-58dd-bd51-00b760fc9380', 'AU-MGV8B', '00000000-0000-0000-0000-000000000001', 'ignatius-of-loyola', 'Ignatius of Loyola', null, 'Ignatius of Loyola (1491 to 1556). Real author. The original text is in the public domain; the workbook around it is new Akana material.', 'ES', null, null, 'en-GB', false, true, 'active'),
  ('d0ae137a-9e13-555b-8ada-5863c303a183', 'AU-Z53HR', '00000000-0000-0000-0000-000000000001', 'matthew-henry', 'Matthew Henry', null, 'Matthew Henry (1662 to 1714). Real author. The original text is in the public domain; the workbook around it is new Akana material.', 'GB', null, null, 'en-GB', false, true, 'active'),
  ('0f9e0c54-8b14-5c64-8e3b-d5126214f0b2', 'AU-TA7MB', '00000000-0000-0000-0000-000000000001', 'f-max-muller', 'F. Max Müller (translator)', null, 'F. Max Müller (1823 to 1900). Real translator. The source text is traditional and anonymous; his English translation is in the public domain. The workbook around it is new Akana material.', null, null, null, 'en-GB', false, true, 'active'),
  ('2d63c105-9865-5c70-8a1a-a1e2d76cc0b9', 'AU-KM3PB', '00000000-0000-0000-0000-000000000001', 'edwin-arnold', 'Edwin Arnold (translator)', null, 'Edwin Arnold (1832 to 1904). Real translator. The source text is traditional and anonymous; his English translation is in the public domain. The workbook around it is new Akana material.', 'GB', null, null, 'en-GB', false, true, 'active'),
  ('5b61abc1-9fcd-544d-b225-ef06a9d84b64', 'AU-HESJ2', '4866fab5-9c14-555e-9cf0-2e1404bdbbb4', 'ruth-okonkwo-harland', 'Ruth Okonkwo-Harland', 'Ruth Okonkwo-Harland', 'Grew up in Enugu and has lived in Leeds since her twenties. Has hosted a midweek prayer group in her front room for many years. Writes plain, slow guides to forgiveness and prayer. This author is invented for the Akana demo.', 'GB', null, null, 'en-GB', true, false, 'active'),
  ('58e0c9b4-4c04-5517-9288-d1037d17258f', 'AU-4SXM8', '55476faa-5c27-525a-b387-e7d091219e00', 'hyejin-park-lindqvist', 'Hyejin Park-Lindqvist', 'Hyejin Park-Lindqvist', 'A Korean-American former high school English teacher in Seattle. Leads a Saturday morning discussion group at her church and makes room for honest questions about faith. This author is invented for the Akana demo.', 'US', null, null, 'en-US', true, false, 'active'),
  ('9e2d1d61-1811-5b4a-b342-77a5767df263', 'AU-NQZGX', '689f9442-c62f-5adb-a5cf-1c184cc21812', 'theodora-vasilakis-reid', 'Theodora Vasilakis-Reid', 'Theodora Vasilakis-Reid', 'Grew up in Melbourne''s Greek community and has taught Sunday school for many years. Writes about the Church year and prayer at home. This author is invented for the Akana demo.', 'AU', null, null, 'en-GB', true, false, 'active'),
  ('600aaa17-cebf-5477-bed1-257df0b19b64', 'AU-C7YJ6', '4ab4c060-f94a-58f9-91e6-120059f4dd69', 'ioana-constantinescu-byrne', 'Ioana Constantinescu-Byrne', 'Ioana Constantinescu-Byrne', 'Moved from Cluj to Dublin in her twenties and sings in a small Orthodox choir. Writes about the evening prayers and psalms she learned as a child. This author is invented for the Akana demo.', 'IE', null, null, 'en-GB', true, false, 'active'),
  ('9d3d4637-ef01-59dc-ae89-2a811e3c18c4', 'AU-E5MP6', '28a7ef0b-9fe5-5ff8-9ba7-bf9c2c7612f2', 'siobhan-carrick-doherty', 'Siobhán Carrick-Doherty', 'Siobhán Carrick-Doherty', 'A retired primary teacher in Cork and a grandmother of five. Has helped families get ready for their children''s First Communion for many years. Writes about prayer around the kitchen table and in the working day. This author is invented for the Akana demo.', 'IE', null, null, 'en-GB', true, false, 'active'),
  ('d980ee31-131f-57da-8d4e-1d77cafb51c5', 'AU-1A05T', '55476faa-5c27-525a-b387-e7d091219e00', 'jerome-whitlock-bayliss', 'Jerome Whitlock-Bayliss', 'Jerome Whitlock-Bayliss', 'Pastored a small congregation in rural Ohio for twenty-six years and now mentors younger pastors. Writes about rest, marriage and pastoral visiting. This author is invented for the Akana demo.', 'US', null, null, 'en-US', true, false, 'active'),
  ('f67b6206-aba7-5cbb-b317-374e72d8f389', 'AU-BT1YF', '7b6fccbd-17b4-5fa1-8a89-752efb676038', 'losa-faleolo-pierce', 'Losa Faleolo-Pierce', 'Losa Faleolo-Pierce', 'A Samoan New Zealander in South Auckland who has led small groups and family evenings at her church for twenty years. Writes for group leaders and busy households. This author is invented for the Akana demo.', 'NZ', null, null, 'en-GB', true, false, 'active'),
  ('3e7232dd-37b5-5860-94aa-52d1009c8d32', 'AU-Q0X8F', '4866fab5-9c14-555e-9cf0-2e1404bdbbb4', 'winsome-clarke-adeyemi', 'Winsome Clarke-Adeyemi', 'Winsome Clarke-Adeyemi', 'Born in Kingston, Jamaica, and raised in south London. Worked in local government finance for thirty years and organises a church food bank rota. Writes about honest work and open-handed living. This author is invented for the Akana demo.', 'GB', null, null, 'en-GB', true, false, 'active'),
  ('1b74df91-1414-5a36-928d-d9611765ff6c', 'AU-Y8MZQ', '0370513a-17d4-5172-b56e-5dd849460ac9', 'agnieszka-lessard-nowak', 'Agnieszka Lessard-Nowak', 'Agnieszka Lessard-Nowak', 'A Polish-Canadian bookkeeper in Winnipeg who has visited bereaved families as a parish volunteer for many years. Writes gently about grief, Lent and simple living. This author is invented for the Akana demo.', 'CA', null, null, 'en-GB', true, false, 'active'),
  ('1f79d0ec-7374-5090-9675-476e437eddb0', 'AU-2DA6H', '00000000-0000-0000-0000-000000000001', 'maya-vaughn', 'Maya Vaughn', null, null, null, null, null, 'en-US', false, false, 'active')
