  ('37224d6d-d0cf-5dcf-9406-02000d7143ed', 'AK-H2K6J', 'bbb332c3-07a7-50bf-95b2-7b9f9af0ad52', '0370513a-17d4-5172-b56e-5dd849460ac9', '00000000-0000-0000-0000-00000000000a', 'kept-company-in-grief-h2k6j', 'Kept Company in Grief', null, 'A gentle companion for the months after someone dies. It does not promise to take grief away.', 'personal_development', 'mercy-and-comfort', 'standard', 'full', 'demo', true, 'draft', null),
  ('e16b8f74-9f05-5c24-8681-49396c1c1e54', 'AK-577PZ', 'a70b6fee-d459-53d0-8ede-4ed6aa5f6e17', '4866fab5-9c14-555e-9cf0-2e1404bdbbb4', '00000000-0000-0000-0000-00000000000a', 'forgiving-slowly-577pz', 'Forgiving Slowly', null, 'Forgiveness as a long road, never a demand to forget or to return to harm.', 'personal_development', 'mercy-and-comfort', 'standard', 'full', 'demo', true, 'draft', null),
  ('a078fbea-1b46-5af3-a4d6-636daf189431', 'AK-G96XJ', '1f7ece6b-6273-51b2-a1de-eb1b67f4f4e2', '4ab4c060-f94a-58f9-91e6-120059f4dd69', '00000000-0000-0000-0000-00000000000a', 'psalms-of-the-long-night-g96xj', 'Psalms of the Long Night', null, 'Pray the lament psalms in hard seasons, with Help now one tap away.', 'personal_development', 'mercy-and-comfort', 'standard', 'full', 'demo', true, 'draft', null),
  ('4f7c5fc8-7847-522a-abbc-403eaf505bf1', 'AK-1QX95', '6d5ec150-3c13-500c-8fdd-2e667d74af2f', '55476faa-5c27-525a-b387-e7d091219e00', '00000000-0000-0000-0000-00000000000a', 'questions-welcome-1qx95', 'Questions Welcome', null, 'Bible people who asked hard questions, and room for yours.', 'personal_development', 'mercy-and-comfort', 'standard', 'full', 'demo', true, 'draft', null),
  ('15af6fdd-5785-5b33-b02f-e1a3b4e4132d', 'AK-DCSC6', '4ff1b56d-7e7f-547f-8689-412b8a5ed7fd', '46f2cd21-9554-55d7-b252-42f53a250723', '00000000-0000-0000-0000-00000000000a', 'welcome-at-the-door-dcsc6', 'Welcome at the Door', null, 'A four-week course for the people who greet, seat and remember newcomers.', 'leadership', 'serving-together', 'none', 'full', 'demo', true, 'draft', null),
  ('d737728b-e067-54cf-88d3-0890c23d6481', 'AK-0G88S', 'c52dcd25-979e-5267-9e98-f5cba08bba44', '7b6fccbd-17b4-5fa1-8a89-752efb676038', '00000000-0000-0000-0000-00000000000a', 'the-small-group-leaders-year-0g88s', 'The Small Group Leader''s Year', null, 'A season of leading a small group, one skill a week.', 'leadership', 'serving-together', 'none', 'full', 'demo', true, 'draft', null),
