-- Akana catalogue seed. Generated by scripts/seed.ts --sql; do not edit by hand.
-- Deterministic: the same inputs give the same file. Re-running upserts in place.
-- workbooks.status is set on insert only, so a title released through public.release_version stays live when the seed runs again.
-- Requires migrations 0001, 0002, 0015 (taxonomy flags) and 0025 (themes.status). The house organisation and marketplace tenant come from 0001.
begin;

-- genres (11)
on conflict (id) do update set
  name = excluded.name,
  default_safety_tier = excluded.default_safety_tier,
  guardrails = excluded.guardrails;

-- shelves (10)
on conflict (id) do update set
  name = excluded.name,
  status = excluded.status,
  sort = excluded.sort,
  hidden_until_min_books = excluded.hidden_until_min_books;

-- areas (19)
on conflict (id) do update set
  shelf_id = excluded.shelf_id,
  name = excluded.name;

-- themes (51)
on conflict (id) do update set
  name = excluded.name,
  line = excluded.line,
  shelf_id = excluded.shelf_id,
  area_id = excluded.area_id,
  topics = excluded.topics,
  clearance_status = excluded.clearance_status,
  min_books = excluded.min_books,
  group_suitable = excluded.group_suitable,
  hidden_until_min_books = excluded.hidden_until_min_books,
  status = excluded.status,
  retired_at = excluded.retired_at,
  retired_reason = excluded.retired_reason;

-- organisations (27)
on conflict (id) do update set
  code = excluded.code,
  kind = excluded.kind,
  legal_name = excluded.legal_name,
  display_name = excluded.display_name,
  slug = excluded.slug,
  country = excluded.country,
  is_demo = excluded.is_demo;

-- authors (97)
on conflict (id) do update set
  code = excluded.code,
  org_id = excluded.org_id,
  slug = excluded.slug,
  display_name = excluded.display_name,
  legal_name = excluded.legal_name,
  bio = excluded.bio,
  country = excluded.country,
  photo_path = excluded.photo_path,
  website = excluded.website,
  spelling = excluded.spelling,
  is_demo = excluded.is_demo,
  is_public_domain = excluded.is_public_domain,
  status = excluded.status;

-- books (190)
on conflict (id) do update set
  org_id = excluded.org_id,
  slug = excluded.slug,
  title = excluded.title,
  subtitle = excluded.subtitle,
  edition = excluded.edition,
  language = excluded.language,
  isbns = excluded.isbns,
  asin = excluded.asin,
  store_links = excluded.store_links,
  cover_path = excluded.cover_path,
  rights_status = excluded.rights_status,
  publisher = excluded.publisher,
  year = excluded.year,
  is_demo = excluded.is_demo;

-- book_contributors (190)
on conflict (book_id, author_id, role) do update set
  death_year = excluded.death_year,
  sort = excluded.sort;

-- workbooks (190)
on conflict (id) do update set
  code = excluded.code,
  book_id = excluded.book_id,
  org_id = excluded.org_id,
  tenant_id = excluded.tenant_id,
  slug = excluded.slug,
  title = excluded.title,
  short_title = excluded.short_title,
  card_line = excluded.card_line,
  genre_id = excluded.genre_id,
  theme_id = excluded.theme_id,
  safety_tier = excluded.safety_tier,
  depth = excluded.depth,
  badge = excluded.badge,
  is_demo = excluded.is_demo,
  licence_ref = excluded.licence_ref;

-- workbook_versions (140)
on conflict (id) do update set
  workbook_id = excluded.workbook_id,
  semver = excluded.semver,
  schema_version = excluded.schema_version,
  content = excluded.content,
  content_hash = excluded.content_hash,
  validated_at = excluded.validated_at,
  published_at = excluded.published_at;

-- tenant_listings (190)
on conflict (tenant_id, workbook_id) do update set
  visible = excluded.visible,
  sort = excluded.sort,
  featured = excluded.featured;

